module OLED_SelData(
	sys_clk,
	rst_n,
	init_req,
	init_data,
	refresh_req,
	refresh_data,
	showfont_req,
	showfont_data,
	show_THdata_req,
	show_THdata,
	show_Lightdata,
	show_Lightdata_req,
	IICWriteReq,
	IICWriteData);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input init_req;
	input [23:0] init_data;
	input refresh_req;
	input [23:0] refresh_data;
	input showfont_req;
	input [23:0] showfont_data;
	input show_THdata_req;
	input [23:0] show_THdata;
	input [23:0] show_Lightdata;
	input show_Lightdata_req;
	output IICWriteReq;
	output [23:0] IICWriteData;

	wire sys_clk;
	wire rst_n;
	wire init_req;
	wire [23:0] init_data;
	wire refresh_req;
	wire [23:0] refresh_data;
	wire showfont_req;
	wire [23:0] showfont_data;
	wire show_THdata_req;
	wire [23:0] show_THdata;
	wire [23:0] show_Lightdata;
	wire show_Lightdata_req;
	wire IICWriteReq;
	wire [23:0] IICWriteData;

	//----Code starts here: integrated by Robei-----
	reg       IICWriteReqReg;
	reg[23:0] IICWriteDataReg; 
	
	assign IICWriteReq  = init_req | showfont_req | refresh_req | show_THdata_req|show_Lightdata_req;
	assign IICWriteData = (init_req == 1'b1) ? init_data : (refresh_req == 1'b1) ? refresh_data : (showfont_req == 1'b1)?showfont_data:(show_THdata_req == 1'b1)?show_THdata:show_Lightdata;
	
	
	
	
endmodule    //OLED_SelData

